package net.officefloor.hq.app.asof;

import java.sql.Connection;
import java.sql.SQLException;
import java.sql.Statement;
import javax.sql.DataSource;
import org.springframework.beans.factory.config.BeanPostProcessor;
import org.springframework.jdbc.datasource.DelegatingDataSource;
import org.springframework.stereotype.Component;

/**
 * Every connection is handed out reading the store as it stands now, or, for a request reading the sheet as of a date
 * ({@link AsOfView}), reading that date's schema with the date as the sheet's today. Set on every hand-out, so a
 * pooled connection never passes one request's view on to the next.
 */
@Component
public class AsOfConnections implements BeanPostProcessor {

    @Override
    public Object postProcessAfterInitialization(Object bean, String beanName) {
        if (bean instanceof DataSource dataSource && !(bean instanceof DelegatingDataSource)) {
            return new DelegatingDataSource(dataSource) {
                @Override
                public Connection getConnection() throws SQLException {
                    return viewed(super.getConnection());
                }

                @Override
                public Connection getConnection(String username, String password) throws SQLException {
                    return viewed(super.getConnection(username, password));
                }
            };
        }
        return bean;
    }

    private static Connection viewed(Connection connection) throws SQLException {
        AsOfView view = AsOfView.current();
        try (Statement s = connection.createStatement()) {
            if (view == null) {
                s.execute("SET SCHEMA PUBLIC");
                s.execute("SET @asof = NULL");
            } else {
                s.execute("SET SCHEMA " + view.schema());
                s.execute("SET @asof = DATE '" + view.date() + "'");
            }
        }
        return connection;
    }
}
package net.officefloor.hq.app.asof;

import java.time.LocalDate;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.function.Supplier;
import org.springframework.stereotype.Component;

/**
 * Reads the sheet as it stood at the end of a date ({@link AsOfView}), with the date standing in for its today, from
 * within a request that changes the store now: the read runs on a thread of its own, outside the request's
 * transaction, so every connection it takes is pointed at that date's schema, exactly as a read of the as-of view is.
 */
@Component
public class AsOfReader {

    private final SheetDayRepository days;
    private final ExecutorService threads = Executors.newCachedThreadPool((r) -> {
        Thread t = new Thread(r, "as-of-read");
        t.setDaemon(true);
        return t;
    });

    public AsOfReader(SheetDayRepository days) {
        this.days = days;
    }

    /** The read's result, made against the sheet as it stood at the end of the date. */
    public <T> T read(String sheetId, LocalDate date, Supplier<T> read) {
        String schema = days.schemaAsOf(sheetId, date);
        try {
            return threads.submit(() -> {
                AsOfView.set(new AsOfView(schema, date));
                try {
                    return read.get();
                } finally {
                    AsOfView.set(null);
                }
            }).get();
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            throw new IllegalStateException("Interrupted reading sheet " + sheetId + " as of " + date, e);
        } catch (ExecutionException e) {
            throw e.getCause() instanceof RuntimeException r ? r
                    : new IllegalStateException("Could not read sheet " + sheetId + " as of " + date, e.getCause());
        }
    }
}
package net.officefloor.hq.app.asof;

import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import java.util.NavigableMap;
import java.util.TreeMap;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.setting.DatedSettings;
import net.officefloor.hq.app.setting.DatedSettings.FromValue;

/**
 * A sheet's figures as they stood at a moment: its people, its claims (newest first), its rates, every dated setting
 * value recorded (by key, oldest first) and its policy date (null: blank).
 */
public record SheetState(List<Person> people, List<Claim> claims, List<Rate> rates,
        Map<String, List<FromValue>> settings, LocalDate policyDate) {

    /** A sheet with nothing on it yet. */
    public static final SheetState EMPTY = new SheetState(List.of(), List.of(), List.of(), Map.of(), null);

    /** The person with this id then, or null when they were not on the sheet. */
    public Person person(long id) {
        return people.stream().filter((p) -> p.id() == id).findFirst().orElse(null);
    }

    /** The person's claims then, newest first. */
    public List<Claim> claimsOf(long personId) {
        return claims.stream().filter((c) -> c.personId() == personId).toList();
    }

    /** The dated settings then. */
    public DatedSettings dated() {
        Map<String, NavigableMap<LocalDate, String>> values = new java.util.LinkedHashMap<>();
        settings.forEach((key, recorded) -> {
            NavigableMap<LocalDate, String> byDate = new TreeMap<>();
            recorded.forEach((v) -> byDate.put(v.from(), v.value()));
            values.put(key, byDate);
        });
        return new DatedSettings(values);
    }
}
package net.officefloor.hq.app.asof;

import java.sql.Date;
import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;
import tools.jackson.databind.json.JsonMapper;

/**
 * The sheet as it stood each time its today was changed, so its figures can be read as they stood at the end of an
 * earlier date: every change made while the sheet's today was on or before that date counts, every later one does
 * not.
 */
@Repository
public class SheetDayRepository {

    private static final JsonMapper JSON = JsonMapper.builder().build();

    private final JdbcTemplate jdbc;
    private final PersonRepository people;
    private final ClaimRepository claims;
    private final RateRepository rates;
    private final SettingRepository settings;
    private final AsOfSchemas schemas;

    public SheetDayRepository(JdbcTemplate jdbc, PersonRepository people, ClaimRepository claims, RateRepository rates,
            SettingRepository settings, AsOfSchemas schemas) {
        this.schemas = schemas;
        this.jdbc = jdbc;
        this.people = people;
        this.claims = claims;
        this.rates = rates;
        this.settings = settings;
    }

    /** Keep the sheet as it stands now, as its today moves from {@code from} to {@code to}. */
    public void record(String sheetId, LocalDate from, LocalDate to) {
        SheetState now = new SheetState(people.findAll(sheetId), claims.findAll(sheetId), rates.findAll(sheetId),
                settings.dated(sheetId).history(), settings.policyDate(sheetId));
        jdbc.update("INSERT INTO sheet_day (sheet_id, from_today, to_today, state, snapshot) VALUES (?, ?, ?, ?, ?)",
                sheetId, Date.valueOf(from), Date.valueOf(to), JSON.writeValueAsString(now), schemas.snapshot(sheetId));
    }

    /**
     * The schema ({@link AsOfSchemas}) holding the sheet as it stood at the end of the date: a snapshot, the sheet as
     * it stands now, or an empty sheet before it was first loaded.
     */
    public String schemaAsOf(String sheetId, LocalDate date) {
        schemas.ensureShared();
        Long kept = keptAsOf(sheetId, date);
        if (kept == null) {
            return AsOfSchemas.LIVE;
        }
        if (kept < 0) {
            return AsOfSchemas.EMPTY;
        }
        String snapshot = jdbc.queryForObject("SELECT snapshot FROM sheet_day WHERE id = ?", String.class, kept);
        return snapshot == null ? AsOfSchemas.LIVE : snapshot;
    }

    /**
     * The sheet as it stood at the end of the date, or null when that is as it stands now (its today has not moved
     * past the date since it was last on or before it). Before the sheet was first loaded nothing was on it.
     */
    public SheetState asOf(String sheetId, LocalDate date) {
        Long kept = keptAsOf(sheetId, date);
        if (kept == null) {
            return null;
        }
        if (kept < 0) {
            return SheetState.EMPTY;
        }
        String state = jdbc.queryForObject("SELECT state FROM sheet_day WHERE id = ?", String.class, kept);
        return JSON.readValue(state, SheetState.class);
    }

    /** The sheet_day kept as the sheet stood at the end of the date; null: as it stands now; -1: empty. */
    private Long keptAsOf(String sheetId, LocalDate date) {
        List<LocalDate> started = jdbc.query("SELECT started FROM sheet WHERE id = ?",
                (rs, n) -> rs.getObject("started", LocalDate.class), sheetId);
        boolean empty = !started.isEmpty() && started.get(0) != null && started.get(0).isAfter(date);
        Long kept = null;
        for (Map<String, Object> day : jdbc.queryForList(
                "SELECT id, from_today, to_today FROM sheet_day WHERE sheet_id = ? ORDER BY id", sheetId)) {
            LocalDate from = ((Date) day.get("from_today")).toLocalDate();
            LocalDate to = ((Date) day.get("to_today")).toLocalDate();
